Q: An exception occurred applying plugin request [id: &#39;dev.flutter.flutter-plugin-loader&#39;, version: &#39;1.0.0&#39;] A: <p>try changing as follows:</p>
<pre><code> pluginManagement {
    def flutterSdkPath = {
        def properties = new Properties()
        file(&quot;local.properties&quot;).withInputStream { properties.load(it) }
        def flutterSdkPath = properties.getProperty(&quot;flutter.sdk&quot;)
        assert flutterSdkPath != null, &quot;flutter.sdk not set in local.properties&quot;
        return flutterSdkPath
    }

    // REMOVE: settings.ext.flutterSdkPath = flutterSdkPath()
    // REMOVE: includeBuild(&quot;${settings.ext.flutterSdkPath}/packages/flutter_tools/gradle&quot;)

    // ADD:
    includeBuild(&quot;$flutterSdkPath/packages/flutter_tools/gradle&quot;)

    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}

plugins {
    id &quot;dev.flutter.flutter-plugin-loader&quot; version &quot;1.0.0&quot;
    id &quot;com.android.application&quot; version &quot;7.4.0&quot; apply false //7.3.0
    id &quot;org.jetbrains.kotlin.android&quot; version &quot;1.8.10&quot; apply false
    id &quot;com.google.gms.google-services&quot; version &quot;4.3.15&quot; apply false
}

include &quot;:app&quot;
</code></pre>
